#include "KS/SRC/ks/wave_shared.h"
#include "KS/SRC/ks/ksreplay_shared.h"

extern bool particle_enable;
void ks_fx_update();

__asm__(".equ Playspeed__8KSReplay, 0x0023CA88");
__asm__(".equ particle_enable, 0x00424CC4");
__asm__(".equ ks_fx_update__Fv, 0x00368818");

void WAVE_ReplayTick(void)
{
	WAVE_TotalSec += WAVE_GetFrameSec();

  if(ksreplay.Playspeed() >= 1.0f)
	  WAVE_TexAnimFrame = WAVETEX_FrameFix(0, WAVE_TexAnimFrame + WAVE_TexAnimSpeed );
	WAVE_ComputeGrid();
	WAVE_ComputeShift();
	WAVE_ComputeStage();
	WAVE_ComputeVTwist();
	WAVE_ComputeSlices();
	WAVE_EmitterUpdate();
	WAVE_SoundUpdate();
	UNDERWATER_ScrollBottom();
	if ( particle_enable )
	{
	  ks_fx_update();
	}

	WAVE_GetBreakInfo(&WAVE_BreakInfo);
}
